sp_widget.client_script:
function loginCtrl($scope, $http, $window, $location, glideUserSession, glideSystemProperties, spUtil) {

	var c = this;

	c.remember_me = c.data.forgetMe ? false : c.data.rememberMeDefault;

	c.data.url_suffix = $scope.portal ? $scope.portal.url_suffix : "";

	c.masked = true;


	/* =========================================================
	   GATENOW CUSTOMIZATION
	   ========================================================= */

	/*
	 * Always send successful applicant login to:
	 *
	 * /applicant?id=applicant_dashboard
	 */

	function getApplicantDashboardUrl() {

		var portalSuffix = "";

		if ($scope.portal && $scope.portal.url_suffix) {
			portalSuffix = $scope.portal.url_suffix;
		}

		/*
		 * Fallback in case portal information is unavailable.
		 */
		if (!portalSuffix) {
			portalSuffix = "applicant";
		}

		return "/" + portalSuffix + "?id=applicant_dashboard";
	}


	/*
	 * Redirect to the applicant dashboard.
	 */
	function redirectToApplicantDashboard() {

		var dashboardUrl = getApplicantDashboardUrl();

		console.log(
			"GateNow: Redirecting to applicant dashboard:",
			dashboardUrl
		);

		$window.location.replace(dashboardUrl);
	}


	/* =========================================================
	   SSO
	   ========================================================= */

	if (!c.data.is_logged_in &&
		c.data.multisso_enabled &&
		c.data.default_idp) {

		var pageId =
			$location.search().id || $scope.page.id;

		var isLoginPage =
			($scope.portal.login_page_dv == pageId) ||
			('login' == pageId);

		c.server.get({
			action: "set_sso_destination",
			pageURI: isLoginPage ?
				getApplicantDashboardUrl() :
				$location.url()
		}).then(function() {

			$window.location =
				"/login_with_sso.do?glide_sso_id=" +
				c.data.default_idp;

		});

	} else if (
		!c.data.is_logged_in &&
		c.data.certAuthRedirect &&
		c.data.cert_based_auth &&
		c.data.certHeader == "true"
	) {

		login(null, null, true);

	}


	/* =========================================================
	   LOGIN
	   ========================================================= */

	c.login = function(username, password, isCertLogin) {

		login(username, password, isCertLogin);

	};


	function login(username, password, isCertLogin) {

		var url =
			spUtil.getURL({
				sysparm_type: 'view_form.login'
			});


		var pageId =
			$location.search().id || $scope.page.id;


		var isLoginPage =
			($scope.portal.login_page_dv == pageId) ||
			('login' == pageId);


		/*
		 * IMPORTANT:
		 *
		 * Always specify the applicant dashboard as the
		 * destination after successful authentication.
		 *
		 * We do NOT pass null here.
		 */

		var applicantDashboardUrl =
			getApplicantDashboardUrl();


		return $http({

			method: 'post',

			url: url,

			data: $.param({

				'sysparm_type': 'login',

				'ni.nolog.user_password': true,

				'remember_me':
					!!c.remember_me ? true : false,

				'user_name': username,

				'user_password': password,

				'get_redirect_url': true,

				'is_direct_redirect': true,

				/*
				 * FORCE Service Portal destination
				 */
				'sysparm_goto_url':
					applicantDashboardUrl,

				/*
				 * MFA destination
				 */
				'mfa_redirect_url':
					applicantDashboardUrl,

				'cert_login':
					!!isCertLogin

			}),

			headers: {

				'Content-Type':
					'application/x-www-form-urlencoded'

			}

		}).then(function(response) {

			if (!response.data) {

				c.message =
					$scope.data.errorMsg;

				return;

			}


			/* =================================================
			   LOGIN SUCCESS
			   ================================================= */

			if (response.data.status == 'success') {

				if (c.data.multiFactorAuthEnabled) {

					if (response.data.session_token) {

						window.g_ck =
							response.data.session_token;

					}


					/*
					 * IMPORTANT:
					 *
					 * Do not trust ServiceNow's calculated
					 * redirect_url.
					 *
					 * Pass our dashboard URL instead.
					 */

					c.server.get({

						action:
							"multi_factor_auth_setup",

						directTo:
							getApplicantDashboardUrl()

					}).then(

						handleLoginResponse.bind(response),

						handleLoginResponse.bind(response)

					);

				} else {

					handleLoginResponse.call(response);

				}

			}


			/* =================================================
			   MFA CODE REQUIRED
			   ================================================= */

			else if (
				response.data.status ==
				'mfa_code_required'
			) {

				$window.location =
					'/validate_multifactor_auth_code.do';

			}


			/* =================================================
			   LOGIN FAILED
			   ================================================= */

			else {

				c.message =
					response.data.message;

				c.password = "";

				c.username = "";

				angular
					.element("#username")
					.focus();

			}

		}, function errorCallback(response) {

			c.message =
				$scope.data.errorMsg;

		});

	}


	/* =========================================================
	   OIDC LOGIN
	   ========================================================= */

	c.oidcLogin = function(idProvider) {

		c.server.get({

			action:
				"set_sso_destination",

			pageURI:
				getApplicantDashboardUrl()

		}).then(function() {

			$window.location =
				"/login_with_sso.do?glide_sso_id=" +
				idProvider;

		});

	};


	/* =========================================================
	   EXTERNAL LOGIN
	   ========================================================= */

	c.externalLogin = function() {

		var applicantDashboardUrl =
			getApplicantDashboardUrl();


		c.server.get({

			action:
				"set_sso_destination",

			pageURI:
				applicantDashboardUrl

		}).then(function() {

			glideSystemProperties.set(
				"glide.authenticate.multisso.enabled",
				true
			);


			glideUserSession
				.getSsoRedirectUrlForUsername(
					c.username
				)
				.then(

					function(url) {

						$window.location =
							url;

					},

					function(err) {

						spUtil.addErrorMessage(
							$scope.data.errorMsg2
						);

					}

				);

		});

	};


	/* =========================================================
	   LOGIN RESPONSE
	   ========================================================= */

	function handleLoginResponse() {

		c.success =
			this.data.message;


		/*
		 * =====================================================
		 * GATENOW CUSTOM REDIRECT
		 * =====================================================
		 *
		 * Do NOT use:
		 *
		 * response.data.redirect_url
		 *
		 * Do NOT use:
		 *
		 * $location.url(...)
		 *
		 * We explicitly send the user to the Service Portal
		 * applicant dashboard.
		 */

		redirectToApplicantDashboard();

	}


	/* =========================================================
	   EXTERNAL LOGIN MODE
	   ========================================================= */

	c.setExternalLogin = function(newVal) {

		c.externalLoginMode =
			newVal;

		if (!newVal) {
			c.masked = true;
		}

	};


	/* =========================================================
	   PASSWORD VISIBILITY
	   ========================================================= */

	c.renderMaskIcon = function() {

		var passwordEle =
			document.getElementById("password");

		var maskEle =
			document.getElementById("mask_icon");

		$(maskEle).tooltip('hide');

		var btnDescription =
			document.getElementById("btnDescription");

		var element =
			document.getElementsByClassName(
				"mask_btn"
			)[0];

		var isPasswordType =
			passwordEle.type === 'password';

		maskEle.classList.toggle(
			'active',
			isPasswordType
		);

		maskEle.setAttribute(
			'data-original-title',
			(isPasswordType) ?
				'${Hide password}' :
				'${Show password}'
		);

		element.setAttribute(
			'aria-label',
			(isPasswordType) ?
				'${Hide password}' :
				'${Show password}'
		);

		passwordEle.type =
			(isPasswordType) ?
				'text' :
				'password';

		btnDescription.textContent =
			(isPasswordType) ?
				'${Password shown}' :
				'${Password hidden}';

	};

}

sp_widget.css:
.sp-login-widget { 

  .panel-body {
    padding: 15px 15px 10px;
  }

  .form-control,
  label[for="username"],
  label[for="password"] {
    color: black;
  }

  .btn {
    font-weight: 600;
    font-size: 2.0rem;
    background-color: $login-btn-bg;
    border-color: $login-btn-border;
  }

  .list-group {
    margin-bottom: 12px;
  }

  .login-button-old {
    margin-top: 7px;
  }

  .login-alert {
    margin-left: 0px;
    margin-right: 0px;
  }

}
//STRY50033370: Forgot Password link in the login widget
//Start -- login widget advanced view
.sp-login-widget.advanced {  
  .panel-title {
    font-size: 25px;
  }

  .panel-default > .panel-heading {
    background-color: $panel-bg; 
    border: 0px;    
  }

  .panel-body {
    padding: 0px 0px 10px;
  }

  [placeholder]::-webkit-input-placeholder { 
    transition: opacity 0.01s 0.01s ease !important; 
    opacity: 0 !important; 
  }

  .form-signin {
    .list-group-item { 
      border: 0px;
    }

    .login-alert {
    margin-left: 15px;
    margin-right: 15px;
    }

    .btn {
      font-weight: 400 !important;
      border-color: $brand-primary;
      background-color: $brand-primary;
      border-radius: 2px;
    }

    .forgot-pwd-div {
      padding-right: 15px;
      padding-left: 15px;
      .forgot-text {
        font-size: 16px;	
        line-height: 20px;
        padding-top: 8px;
      }

      .btn {
        line-height: 16px;
        font-size: 14px;
        margin-top: 0px;
      }

    }

    .submit-btn {
      padding-right: 15px;
      padding-left: 15px;
    }

    .input-group-advanced {
      margin-top: 10px;
    }

    .input-advanced {
      border: 1px solid $btn-default-border !important;
      border-radius: 3px !important;
      background-color: $panel-bg !important;
    }

    .checkbox {
      padding-left: 15px !important; 
    }

    .label-advanced {
      position: relative;
      width: 100%;
      padding: 0;
      overflow: visible;
      border: 0;
      height: 19px;
      color: $text-color;
      font-size: 16px;
      line-height: 19px;
    }

    .mask_btn {
      background-color: #fcfcfc;
      border-color: #939393;
      border-left : 0px;
      width:fit-content;
      border-top-left-radius: 0px !important;
      border-bottom-left-radius: 0px !important;
      font-size: 1.4rem !important;
      position: relative;

	&.active {
		&:after {
          	background-color: #2e2e2e;
			content: "";
			height: 16px;
			left: 50%;
	    		margin-top: -8px;
			margin-inline-start: -1px;
			margin-block-start: -8px;
			position: absolute;
			top: 50%;
			transform: rotate(45deg);
			width: 1px;
			}
		}
    }


    .loginWithBtn {
      padding: 0 1.5rem;
    }

  }

}
//End -- login widget advanced view
.sp-self-registration {
  text-align: center;
}
.sp-login-widget {
.bar {
  margin: 12px 0;
  span {
        display: flex;
        text-wrap: nowrap;

    &:before, &:after {
      content: '';
          width: 100%;
      height: 1px;
      background-color: #b3bac7;
          margin-top: 10px;
    }
    &:before {
          margin-right: 10px;
    }
    &:after {
          margin-left: 10px;
        }
    }
  }
button.cert, a.idp {
  background-color: #fff !important;
  border-color: #ccc !important;
  width: 100%;
  margin-bottom: 10px;

  &:hover {
    border-color: #adadad;
    background-color: #e6e6e6;
  }
  img {
    height: 20px;
    width: 20px;
    margin-bottom: 3px;
    margin-right: 9px;
  }
}
  img.eye-icon {
    content:url("eye.svg");
    cursor: pointer;
    width:18px;
    height:18px;
    display: flex;
    justify-content:center;
    align-items:center;
    float:left;
  }

  img.eye-icon.slashed {
    content:url("eye-slash.svg");
  }

  .password-group {
    display:flex;
    flex-direction:row;
  }

  .mask_btn {
      background-color: #fcfcfc;
      border-color: #939393;
      border-left : 0px;
      width:fit-content;
      border-top-left-radius: 0px !important;
      border-bottom-left-radius: 0px !important;
      font-size: 1.4rem !important;
      position: relative;

	&.active {
		&:after {
          	background-color: #2e2e2e;
			content: "";
			height: 16px;
			left: 50%;
	    		margin-top: -8px;
			margin-inline-start: -1px;
			margin-block-start: -8px;
			position: absolute;
			top: 50%;
			transform: rotate(45deg);
			width: 1px;
			}
		}
    }
  input::-ms-reveal,
    input::-ms-clear {
      display: none;
  }
}

sp_widget.script:
(function() {

    options.show_panel =
        options.show_panel == "true" ||
        options.show_panel == true;


    /* =========================================================
       GATENOW DASHBOARD URL
       ========================================================= */

    var GATENOW_DASHBOARD =
        '/applicant?id=applicant_dashboard';


    /* =========================================================
       MULTI-FACTOR AUTHENTICATION
       ========================================================= */

    if (
        input &&
        input.action === "multi_factor_auth_setup"
    ) {

        if (
            gs.getSession()
              .getProperty(
                  "setup_multifactor_authn"
              )
        ) {

            /*
             * Ignore the redirect supplied by the
             * standard login widget.
             *
             * Force GateNow dashboard.
             */

            gs.getSession()
              .putProperty(
                  "nav_to",
                  GATENOW_DASHBOARD
              );


            gs.getSession()
              .putProperty(
                  "starting_page",
                  GATENOW_DASHBOARD
              );


            gs.getSession()
              .putProperty(
                  "is_direct_redirect",
                  "true"
              );

        }

        return;
    }


    /* =========================================================
       SSO SELECTOR FIELD
       ========================================================= */

    var ssoSelectorField =
        gs.getProperty(
            'glide.authenticate.multisso.login_locate.user_field',
            'user_name'
        );


    var td =
        new GlideTableDescriptor('sys_user');


    var ed =
        td.getElementDescriptor(
            ssoSelectorField
        );


    if (ed) {

        data.ssoSelectorFieldLabel =
            ed.getLabel();

    }


    /* =========================================================
       SSO DESTINATION
       ========================================================= */

    if (
        input &&
        input.action === "set_sso_destination"
    ) {

        /*
         * Clear existing native destination.
         */

        var gs_nav_to =
            gs.getSession()
              .getProperty("nav_to");


        gs.getSession()
          .putProperty(
              "nav_to",
              null
          );


        /*
         * Always use GateNow dashboard when
         * the login originates from this portal.
         */

        gs.getSession()
          .putProperty(
              "is_direct_redirect",
              "true"
          );


        gs.getSession()
          .putProperty(
              "starting_page",
              GATENOW_DASHBOARD
          );


        return;
    }


    /* =========================================================
       SELF REGISTRATION
       ========================================================= */

    var portalRecord =
        $sp.getPortalRecord();


    var self_registration_field =
        portalRecord ?
        portalRecord.getValue(
            "user_registration_config"
        ) :
        "";


    if (self_registration_field) {

        var registration_config =
            new GlideRecord(
                "sys_user_registration_config"
            );


        registration_config.addActiveQuery();


        registration_config.query(
            'sys_id',
            self_registration_field
        );


        if (registration_config.next()) {

            var self_registration_record_producer =
                registration_config.getValue(
                    "record_producer"
                );


            var self_registration_label =
                registration_config.getValue(
                    "registration_label"
                ) ||
                gs.getMessage("Sign Up");


            data.self_registration_record_producer =
                self_registration_record_producer;


            data.self_registration_label =
                self_registration_label;

        }
    }


    /* =========================================================
       CERTIFICATE AUTHENTICATION
       ========================================================= */

    if (
        portalRecord &&
        (
            portalRecord.getValue(
                'enable_certificate_based_authentication'
            ) == 1
        )
    ) {

        data.cert_based_auth =
            gs.getProperty(
                'glide.authenticate.mutual.enabled',
                'false'
            ) == 'true';

    }


    /* =========================================================
       CERTIFICATE HEADER
       ========================================================= */

    if (data.cert_based_auth) {

        var request =
            GlideTransaction
                .get()
                .getRequest();


        var certHeader =
            request.getHeader(
                "X-Client-Cert"
            );


        if (!certHeader) {

            data.certHeader =
                "false";


            gs.log(
                "Failed to register PIV/CAC certificate to the user account."
            );

        } else {

            data.certHeader =
                "true";

        }

    }


    /* =========================================================
       SSO / IDENTITY PROVIDERS
       ========================================================= */

    data.isShowLoginWithIdps =
        false;


    data.isMultiSSOActive =
        gs.getProperty(
            'glide.authenticate.multisso.enabled',
            'false'
        ) == 'true';


    var gr =
        new GlideRecord(
            "sso_properties"
        );


    if (
        data.isMultiSSOActive &&
        gr.isValid()
    ) {

        var ssoUtil =
            new MultiSSO_OidcUtil();


        data.ssoRecords =
            ssoUtil.getSSORecords();


        data.isShowLoginWithIdps =
            (
                data.ssoRecords.length > 0
            );

    }


    /* =========================================================
       PASSWORD RESET
       ========================================================= */

    data.pswdResetUrl =
        gs.getProperty(
            'glide.security.password_reset.uri'
        );


    data.forgotPwdLinkProp =
        gs.getProperty(
            'glide.security.forgot_password.display.link'
        );


    /* =========================================================
       MESSAGES
       ========================================================= */

    data.errorMsg =
        gs.getMessage(
            "There was an error processing your request"
        );


    data.errorMsg2 =
        gs.getMessage(
            "An error has occurred - please contact your system administrator"
        );


    data.passwordMsg =
        gs.getMessage(
            "Password"
        );


    data.usernameMsg =
        gs.getMessage(
            "User name"
        );


    /* =========================================================
       LOGIN SETTINGS
       ========================================================= */

    data.forgetMe =
        GlideProperties.getBoolean(
            "glide.ui.forgetme"
        );


    data.rememberMeDefault =
        GlideProperties.getBoolean(
            'glide.ui.remember.me.default',
            true
        );


    data.is_logged_in =
        gs.getSession()
          .isLoggedIn();


    var bypass_sso =
        options.bypass_sso == "true";


    data.multisso_enabled =
        !bypass_sso &&
        GlideProperties.getBoolean(
            "glide.authenticate.multisso.enabled"
        );


    data.default_idp =
        GlideProperties.get(
            "glide.authenticate.sso.redirect.idp"
        );


    data.pageURI =
        new GlideSPUtil()
            .getPageUri();


    data.multiFactorAuthEnabled =
        GlideProperties.getBoolean(
            'glide.authenticate.multifactor',
            false
        );


    data.certAuthRedirect =
        gs.getProperty(
            'glide.authenticate.cert.redirect.enable',
            'false'
        ) == 'true';


    /* =========================================================
       CUSTOM URL / SSO
       ========================================================= */

    var customURL =
        GlideProperties.getBoolean(
            'glide.customurl.enabled',
            false
        );


    if (
        customURL == true &&
        data.multisso_enabled == true
    ) {

        var idp =
            SNC.CustomURLSPUtil
              .getAutoRedirectIDPForCustomURLWithPortal();


        if (
            GlideStringUtil.notNil(idp)
        ) {

            data.default_idp =
                idp;

        }

    }


    /* =========================================================
       SESSION ACCESS MESSAGE
       ========================================================= */

    var isSessionAccessReduced =
        GlideSession
            .get()
            .getBooleanProperty(
                "isSessionAccessReduced",
                false
            );


    var isSessionAccessMessageShown =
        GlideSession
            .get()
            .getBooleanProperty(
                "isSessionAccessReducedMessageShown",
                false
            );


    if (
        isSessionAccessReduced &&
        !isSessionAccessMessageShown
    ) {

        SNC.SessionAccessUtil
            .showUserInfoMessageIfAccessReduced();

    }

})();
